```java
public void toSource(final CodeBuilder cb,
                       final int inputSeqNum,
                       final Node root) {
    runInCompilerThread(new Callable<Void>() {
      @Override
      public Void call() throws Exception {
        // Validate root node type early to prevent partial side effects on cb.
        Preconditions.checkState(root.getType() == Token.SCRIPT,
            "Root node must be of type SCRIPT for toSource operation.");

        // Ensure options are initialized before accessing them.
        // This check is defensive; in a well-managed Compiler, options should always be set.
        Preconditions.checkNotNull(options, "Compiler options must be initialized.");

        if (options.printInputDelimiter) {
          // Ensure delimiter starts on a new line if there's existing content.
          if ((cb.getLength() > 0) && !cb.endsWith("\n")) {
            cb.append("\n");
          }

          String delimiter = options.inputDelimiter;

          // Retrieve source name and perform null/empty checks.
          String sourceName = (String) root.getProp(Node.SOURCENAME_PROP);
          Preconditions.checkState(sourceName != null && !sourceName.isEmpty(),
              "Source name property (SOURCENAME_PROP) must be present and non-empty on the root node.");

          // Replace placeholders in the delimiter.
          delimiter = delimiter.replaceAll("%name%", sourceName)
            .replaceAll("%num%", String.valueOf(inputSeqNum));

          cb.append(delimiter).append("\n");
        }

        // Append JSDoc license information if available.
        if (root.getJSDocInfo() != null && root.getJSDocInfo().getLicense() != null) {
          cb.append("/*\n")
            .append(root.getJSDocInfo().getLicense())
            .append("*/\n");
        }

        // If a source map is configured, inform it about the starting position
        // of the generated code in the CodeBuilder.
        if (options.sourceMapOutputPath != null) {
          // Ensure sourceMap is not null before accessing it.
          Preconditions.checkNotNull(sourceMap, "Source map must be initialized if sourceMapOutputPath is set.");
          sourceMap.setStartingPosition(
              cb.getLineIndex(), cb.getColumnIndex());
        }

        // Generate the actual JavaScript code from the AST node.
        String code = toSource(root, sourceMap);

        if (!code.isEmpty()) {
          cb.append(code);

          // Append a semicolon if the code doesn't already end with one,
          // to prevent parse ambiguity when files are concatenated.
          int length = code.length();
          char lastChar = code.charAt(length - 1);
          char secondLastChar = length >= 2 ?
              code.charAt(length - 2) : '\0';
          boolean hasSemiColon = lastChar == ';' ||
              (lastChar == '\n' && secondLastChar == ';');
          if (!hasSemiColon) {
            cb.append(";");
          }
        }
        // If code is empty, no semicolon is appended, which is correct.
        // The delimiter (if printed) already includes a newline.

        return null;
      }
    });
  }
```

