import org.apache.commons.compress.archivers.ar.ArArchiveInputStream;
import org.apache.commons.compress.archivers.cpio.CpioArchiveInputStream;
import org.apache.commons.compress.archivers.dump.DumpArchiveInputStream;
import org.apache.commons.compress.archivers.jar.JarArchiveInputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ArchiveStreamFactory {

    private static final Logger LOGGER = LoggerFactory.getLogger(ArchiveStreamFactory.class);

    public static final String AR = "ar";
    public static final String CPIO = "cpio";
    public static final String DUMP = "dump";
    public static final String JAR = "jar";
    public static final String TAR = "tar";
    public static final String ZIP = "zip";

    public ArchiveInputStream createArchiveInputStream(final InputStream in)
            throws ArchiveException {
        if (in == null) {
            throw new IllegalArgumentException("Stream must not be null.");
        }

        if (!in.markSupported()) {
            throw new IllegalArgumentException("Mark is not supported by the provided InputStream.");
        }

        try {
            // Attempt to identify common archive types with smaller signatures first
            final byte[] signature = new byte[12];
            in.mark(signature.length);
            int signatureLength = in.read(signature);
            in.reset();

            if (ZipArchiveInputStream.matches(signature, signatureLength)) {
                LOGGER.debug("Detected ZIP archive format.");
                return new ZipArchiveInputStream(in);
            } else if (JarArchiveInputStream.matches(signature, signatureLength)) {
                LOGGER.debug("Detected JAR archive format.");
                return new JarArchiveInputStream(in);
            } else if (ArArchiveInputStream.matches(signature, signatureLength)) {
                LOGGER.debug("Detected AR archive format.");
                return new ArArchiveInputStream(in);
            } else if (CpioArchiveInputStream.matches(signature, signatureLength)) {
                LOGGER.debug("Detected CPIO archive format.");
                return new CpioArchiveInputStream(in);
            }

            // Dump needs a bigger buffer to check the signature
            final byte[] dumpsig = new byte[32];
            in.mark(dumpsig.length);
            signatureLength = in.read(dumpsig);
            in.reset();
            if (DumpArchiveInputStream.matches(dumpsig, signatureLength)) {
                LOGGER.debug("Detected DUMP archive format.");
                return new DumpArchiveInputStream(in);
            }

            // Tar needs an even bigger buffer to check the signature; read the first block
            final byte[] tarheader = new byte[512];
            in.mark(tarheader.length);
            signatureLength = in.read(tarheader);
            in.reset();

            // COMPRESS-117 - improve auto-recognition for TAR
            // First, check the basic signature. If it matches, attempt a more robust validation.
            if (TarArchiveInputStream.matches(tarheader, signatureLength)) {
                try (TarArchiveInputStream tais = new TarArchiveInputStream(new ByteArrayInputStream(tarheader))) {
                    // Attempt to read the first entry to confirm it's a valid TAR.
                    // This can throw IOException or IllegalArgumentException if the header is malformed.
                    if (tais.getNextEntry() != null) {
                        LOGGER.debug("Detected TAR archive format after robust validation.");
                        return new TarArchiveInputStream(in);
                    }
                } catch (final IOException | IllegalArgumentException e) {
                    // This indicates the TAR header was malformed despite initial signature match.
                    // Log the issue but continue to throw ArchiveException if no other format matches.
                    LOGGER.debug("Initial TAR signature matched, but robust validation failed: {}", e.getMessage());
                    // Do not re-throw here, let the final ArchiveException handle it if no other type matches.
                }
            }

        } catch (final IOException e) {
            throw new ArchiveException("Failed to read from stream or reset mark operations.", e);
        }

        throw new ArchiveException("No Archiver found for the stream signature. " +
                                   "Ensure the stream contains a supported archive format and supports mark/reset.");
    }

    // Other methods (omitted for brevity, assume they are unchanged)
    public ArchiveInputStream createArchiveInputStream( final String archiverName, final InputStream in) throws ArchiveException { return null; }
    public ArchiveOutputStream createArchiveOutputStream( final String archiverName, final OutputStream out) throws ArchiveException { return null; }
}
