public static long parseOctal(final byte[] buffer, final int offset, final int length) {
    // Robustness: Null buffer check
    if (buffer == null) {
        throw new IllegalArgumentException("Buffer cannot be null.");
    }

    // Robustness: Comprehensive offset and length bounds checking
    if (offset < 0 || length < 0 || offset + length > buffer.length) {
        throw new IndexOutOfBoundsException(
                "Offset or length out of bounds: offset=" + offset + ", length=" + length + ", buffer.length=" + buffer.length);
    }

    // Logical Mistake: Ensure minimum length check is first to prevent AIOOBE in subsequent checks
    if (length < 1) { // A length of 0 or 1 cannot represent a meaningful octal number after trimming
        throw new IllegalArgumentException("Length " + length + " must be at least 1 for potential octal parsing.");
    }

    long result = 0;
    int currentStart = offset;
    int currentEnd = offset + length;

    // Optimization/Edge Case: If the first byte is 0, and it's the only content, return 0.
    // This handles cases where a field is explicitly zeroed out.
    // This check is now safe due to the length >= 1 validation.
    if (buffer[currentStart] == 0 && length == 1) {
        return 0L;
    }

    // Skip leading spaces
    while (currentStart < currentEnd) {
        if (buffer[currentStart] == ' ') {
            currentStart++;
        } else {
            break;
        }
    }

    // Trim all trailing NULs and spaces.
    // The ustar and POSIX tar specs require a trailing NUL or
    // space but some implementations use the extra digit for big
    // sizes/uids/gids ...
    // Logical Mistake: Corrected trimming logic to prevent off-by-one and over-trimming.
    // Ensure currentEnd - 1 is always a valid index within the original segment.
    while (currentStart < currentEnd) {
        byte trailer = buffer[currentEnd - 1];
        if (trailer == 0 || trailer == ' ') {
            currentEnd--;
        } else {
            break;
        }
    }

    // Logical Mistake: More descriptive message if the string becomes empty after trimming.
    if (currentStart == currentEnd) {
        throw new IllegalArgumentException(
                "Octal string is empty or contains only spaces/NULs after trimming. " +
                "Original buffer segment: " + new String(buffer, offset, length) +
