public void close() throws IOException {
    // Use a synchronized block to ensure thread-safety for the closed flag and resource closure.
    // This prevents multiple threads from attempting to close concurrently.
    synchronized (this) {
        if (closed) {
            return; // Already closed, do nothing.
        }

        IOException finishException = null;
        IOException bufferCloseException = null;
        IOException outCloseException = null;

        try {
            // Ensure all pending data is written and EOF markers are added.
            // This must happen before closing the underlying streams.
            finish();
        } catch (IOException e) {
            finishException = e;
            // Log the exception if a logger is available, but continue to try closing other resources.
            // For this example, we'll just store it.
        }

        try {
            // Close the TarBuffer, which might flush its own internal buffers.
            if (buffer != null) { // Defensive null check, though 'final' fields are usually non-null.
                buffer.close();
            }
        } catch (IOException e) {
            bufferCloseException = e;
            // Log the exception, but continue.
        }

        try {
            // Close the underlying OutputStream.
            if (out != null) { // Defensive null check.
                out.close();
            }
        } catch (IOException e) {
            outCloseException = e;
            // Log the exception.
        } finally {
            // Mark as closed regardless of whether exceptions occurred during closing.
            // This ensures subsequent calls to close() are idempotent and do nothing.
            closed = true;
        }

        // Re-throw the first encountered exception to inform the caller of a failure.
        // This prioritizes the finish() exception, then buffer, then out.
        if (finishException != null) {
            throw finishException;
        }
        if (bufferCloseException != null) {
            throw bufferCloseException;
        }
        if (outCloseException != null) {
            throw outCloseException;
