public void close() throws IOException {
    // Use a synchronized block to ensure thread-safety during closure.
    // This prevents multiple threads from attempting to close concurrently.
    synchronized (this) {
        if (!this.closed) {
            try {
                // Ensure all pending entries are finished and the archive is properly terminated.
                this.finish();
            } finally {
                // Attempt to close the underlying output stream.
                // This is done in a finally block to ensure the stream is closed
                // even if finish() throws an exception.
                // The 'closed' flag is set to true here to mark the stream as closed
                // regardless of whether out.close() succeeds or fails, preventing
                // subsequent attempts to close a potentially broken stream.
                try {
                    out.close();
                } finally {
                    // Mark as closed regardless of whether out.close() succeeded or failed.
                    // This prevents subsequent calls from attempting to close again.
                    this.closed = true;
                }
            }
        }
    }
}
