public Element previousElementSibling() {
    // Handle the case where the element has no parent.
    // An element without a parent cannot have siblings.
    Element parent = parent();
    if (parent == null) {
        return null;
    }

    List<Element> siblings = parent.children();
    // Find the index of the current element within its parent's children list.
    // The indexInList method is assumed to return null if 'this' is not found,
    // or a non-negative integer if found.
    Integer index = indexInList(this, siblings);

    // If the element is not found in its parent's children list (which shouldn't
    // happen in a consistent DOM, but is a robustness check), or if it's the
    // first child (index 0), there is no previous element sibling.
    if (index == null || index <= 0) {
        return null;
    } else {
        // Return the element immediately preceding the current element.
        return siblings.get(index - 1);
    }
}
