import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.helper.Validate;
import org.jsoup.safety.Whitelist;

public class Cleaner {
    private Whitelist whitelist;

    public Cleaner(Whitelist whitelist) {
        Validate.notNull(whitelist, "Whitelist must not be null");
        this.whitelist = whitelist;
    }

    // Assuming ElementMeta and other private methods are defined elsewhere in the class
    // private ElementMeta createSafeElement(Element sourceEl) { ... }
    // private int copySafeNodes(Element source, Element dest) { ... }

    /**
     * Cleans the input HTML document, removing all elements and attributes that are not
     * permitted by the {@link Whitelist} configured for this {@code Cleaner} instance.
     * This method processes both the {@code <head>} and {@code <body>} sections of the document.
     *
     * @param dirtyDocument The document to clean. Must not be null.
     * @return A new, clean {@link Document} containing only safe HTML. The original document is not modified.
     *         If the dirty document's body is null, the clean document's body will be empty.
     *         If the dirty document's head is null, the clean document's head will be empty.
     * @throws IllegalArgumentException if {@code dirtyDocument} is null.
     */
    public Document clean(Document dirtyDocument) {
        Validate.notNull(dirtyDocument, "Dirty document must not be null");

        // Create a new shell document with the same base URI
        Document clean = Document.createShell(dirtyDocument.baseUri());

        // Process and copy safe nodes from the head of the dirty document to the head of the clean document
        Element dirtyHead = dirtyDocument.head();
        if (dirtyHead != null) {
            copySafeNodes(dirtyHead, clean.head());
        }

        // Process and copy safe nodes from the body of the dirty document to the body of the clean document
