public Complex divide(Complex divisor)
        throws NullArgumentException {
        MathUtils.checkNotNull(divisor);

        // Handle NaN cases first: if either operand is NaN, the result is NaN.
        if (isNaN || divisor.isNaN) {
            return NaN;
        }

        // Handle division by zero (0 + 0i)
        if (divisor.getReal() == 0.0 && divisor.getImaginary() == 0.0) {
            // If 'this' is also zero, it's 0/0, which is NaN.
            // If 'this' is non-zero, it's X/0, which is NaN.
            return NaN;
        }

        // Handle cases involving Infinity
        // If divisor is infinite and 'this' is finite, result is ZERO.
        if (divisor.isInfinite() && !isInfinite()) {
            return ZERO;
        }

        // Corrected: If 'this' is infinite and divisor is finite, result is INF.
        // This covers cases like (INF, 0) / (1, 0) which should be (INF, 0)
        if (isInfinite() && !divisor.isInfinite()) {
            return INF;
        }

        // If both are infinite, the result is NaN (indeterminate form INF/INF)
        if (isInfinite() && divisor.isInfinite()) {
            return NaN;
        }

        final double c = divisor.getReal();
        final double d = divisor.getImaginary();

        // Robust division algorithm to prevent overflow/underflow
        // Scale by the larger of |c| or |d|
        if (FastMath.abs(c) < FastMath.abs(d)) {
            double q = c / d;
            double denominator = c * q + d; // d * (c/d) + d = c + d
            return createComplex((real * q + imaginary) / denominator,
                (imaginary * q - real) / denominator);
        } else {
            double q = d / c;
            double denominator = d * q + c; // c * (d/c) + c = d + c
            return createComplex((imaginary * q + real) / denominator,
                (imaginary - real * q) / denominator);
        }
    }
