```java
public double toDouble() {
    // Handle special values first
    if (isNaN()) {
        return Double.NaN;
    }
    if (isInfinite()) {
        return lessThan(getZero()) ? Double.NEGATIVE_INFINITY : Double.POSITIVE_INFINITY;
    }
    if (equals(getZero())) { // Explicitly handle zero
        return 0.0;
    }

    Dfp currentDfp = this;
    boolean negate = false;
    if (lessThan(getZero())) {
        currentDfp = negate();
        negate = true;
    }

    // IEEE 754 double-precision floating-point format:
    // Sign (1 bit) | Exponent (11 bits) | Mantissa (52 bits)
    // Bias for exponent is 1023.
    // Normal numbers: 1.mantissa * 2^(exponent - 1023)
    // Subnormal numbers: 0.mantissa * 2^(-1022)

    // Find the exponent (unbiased)
    // Estimate using log10, then refine with powers of 2
    int exponent = (int) (currentDfp.log10() * 3.321928094887362); // log2(10) approx 3.3219

    // Adjust initial estimate to ensure tempDfp is less than or equal to currentDfp
    // This loop finds the largest power of 2 (2^exponent) that is less than or equal to currentDfp
    Dfp tempDfp = DfpMath.pow(getTwo(), exponent);
    while (tempDfp.greaterThan(currentDfp)) {
        exponent--;
        tempDfp = DfpMath.pow(getTwo(), exponent);
    }
    while (tempDfp.multiply(getTwo()).lessThan(currentDfp) || tempDfp.multiply(getTwo()).equals(currentDfp)) {
        exponent++;
        tempDfp = DfpMath.pow(getTwo(), exponent);
    }
    // At this point, tempDfp = 2^exponent, and 2^exponent <= currentDfp < 2^(exponent+1)

    // Now, normalize currentDfp to be between 1 (inclusive) and 2 (exclusive)
    // This gives us the mantissa part (1.fraction)
    currentDfp = currentDfp.divide(tempDfp); // currentDfp is now in [1, 2)

    // Extract the fractional part of the mantissa
    // For normal numbers, the leading '1' is implicit. We need the 52 bits after the decimal point.
    // So, subtract 1 (the implicit leading bit)
    // Then multiply by 2^52 to shift the fractional part into an integer.
    long mantissaBits = 0;
    final Dfp TWO_POW_52 = newInstance(4503599627370496L); // 2^52

    if (exponent >= Double.MIN_EXPONENT) { // Normal numbers
        currentDfp = currentDfp.subtract(getOne()); // Remove the implicit leading '1'
        currentDfp = currentDfp.multiply(TWO_POW_52);
        mantissaBits = currentDfp.rint().longValue(); // Round to nearest integer
    } else { // Subnormal numbers or zero
        // For subnormal numbers, the exponent is fixed at -1022 (biased 0).
        // The value is 0.mantissa * 2^(-1022).
        // We need to scale the original number by 2^(1022 + 52) to get the mantissa bits.
        // The effective exponent for subnormals is -1022.
        // The mantissa is 52 bits, so we need to scale by 2^(1022 + 52) = 2^1074
        // The original currentDfp is already scaled by 2^exponent.
        // We need to scale it to 0.mantissa * 2^(-1022).
        // So, currentDfp (which is in [1,2) after division by 2^exponent) needs to be
        // multiplied by 2^(exponent - (-1022)) and then by 2^52.
        // This simplifies to currentDfp * 2^(exponent + 1022 + 52)
        // Or, more simply, the original Dfp value needs to be multiplied by 2^(1022 + 52)
        // to get the mantissa bits directly.

        // Re-calculate from the original (positive) Dfp value for subnormals
        Dfp subnormalScaler = DfpMath.pow(getTwo(), 1074); // 2^(1022 + 52)
        currentDfp = this.negate ? this.negate().multiply(subnormalScaler) : this.multiply(subnormalScaler);
        mantissaBits = currentDfp.rint().longValue();
        exponent = Double.MIN_EXPONENT - 1; // Indicate subnormal (biased exponent 0)
    }

    // Handle special case where mantissa rounds up to 2^52
    if (mantissaBits == 4503599627370496L) { // If mantissa is 2^52
        mantissaBits = 0; // Mantissa becomes 0
        exponent++;       // Exponent increments
    }

    // Check for overflow (exponent too large for double)
    if (exponent > Double.MAX_EXPONENT) {
        return negate ? Double.NEGATIVE_INFINITY : Double.POSITIVE_INFINITY;
    }

    // Construct the double bits
    long bits;
    if (exponent <= Double.MIN_EXPONENT) { // Subnormal or zero
        // For subnormal, biased exponent is 0.
        // The mantissa bits are directly used.
        // The exponent is effectively -1022.
        bits = mantissaBits; // Mantissa bits are already scaled correctly
    } else { // Normal number
        // Biased exponent = exponent + 1023
        bits = mantissaBits | ((long) (exponent + 1023) << 52);
    }

    double result = Double.longBitsToDouble(bits);

    if (negate) {
        result = -result;
    }

    return result;
}
