public double getWeightedRMS() {
    if (rows <= 0) {
        // If there are no observations or an invalid number of rows,
        // the weighted RMS is undefined or zero. Returning 0.0 is a common
        // convention for such cases, indicating no error.
        // Alternatively, an IllegalArgumentException could be thrown if
        // a non-positive 'rows' is considered an invalid state.
        // For an optimizer, 'rows' should ideally always be positive.
        return 0.0;
    }
    if (residuals == null || residualsWeights == null) {
        // This indicates an uninitialized or invalid state of the optimizer.
        // Throwing an IllegalStateException is appropriate.
        throw new IllegalStateException("Residuals or residuals weights are not initialized.");
    }
    if (residuals.length < rows || residualsWeights.length < rows) {
        // This indicates an inconsistency in the internal state.
        throw new IllegalStateException("Residuals or residuals weights arrays are shorter than 'rows'.");
    }

    double weightedSumOfSquares = 0;
    for (int i = 0; i < rows; ++i) {
        final double residual = residuals[i];
        weightedSumOfSquares += residual * residual * residualsWeights[i];
    }
    return Math.sqrt(weightedSumOfSquares / rows);
}
