public static GJChronology getInstance(
            DateTimeZone zone,
            ReadableInstant gregorianCutover,
            int minDaysInFirstWeek) {

        // 1. Input validation for minDaysInFirstWeek
        if (minDaysInFirstWeek < 1 || minDaysInFirstWeek > 7) {
            throw new IllegalArgumentException("Invalid minDaysInFirstWeek: " + minDaysInFirstWeek + ". Must be in range [1, 7].");
        }

        zone = DateTimeUtils.getZone(zone);
        Instant cutoverInstant;
        if (gregorianCutover == null) {
            cutoverInstant = DEFAULT_CUTOVER;
        } else {
            cutoverInstant = gregorianCutover.toInstant();
        }

        GJChronology chrono;
        // Use only the inner synchronized block for cache protection.
        // The 'static synchronized' on the method is redundant and removed.
        synchronized (cCache) {
            ArrayList<GJChronology> chronos = cCache.get(zone);
            if (chronos == null) {
                chronos = new ArrayList<GJChronology>(2);
                cCache.put(zone, chronos);
            } else {
                for (int i = chronos.size(); --i >= 0;) {
                    chrono = chronos.get(i);
                    if (minDaysInFirstWeek == chrono.getMinimumDaysInFirstWeek() &&
                        cutoverInstant.equals(chrono.getGregorianCutover())) {

                        return chrono;
                    }
                }
            }

            // Corrected logic for non-UTC zones:
            // Create zoned Julian and Gregorian chronologies directly.
            if (zone == DateTimeZone.UTC) {
                chrono = new GJChronology
                    (JulianChronology.getInstance(zone, minDaysInFirstWeek),
                     GregorianChronology.getInstance(zone, minDaysInFirstWeek),
                     cutoverInstant);
            } else {
                // For non-UTC zones, create zoned Julian and Gregorian chronologies
                // and then construct GJChronology with them.
                // This avoids the problematic ZonedChronology wrapping of an already
                // constructed GJChronology with UTC internal components.
                JulianChronology julian = JulianChronology.getInstance(zone, minDaysInFirstWeek);
                GregorianChronology gregorian = GregorianChronology.getInstance(zone, minDaysInFirstWeek);
                chrono = new GJChronology(julian, gregorian, cutoverInstant);
            }
            chronos.add(chrono);
        }
        return chrono;
    }
